 if(!empty($_SESSION['admin_id'])){$q=$pdo->prepare('SELECT id,username,name FROM admins WHERE id=?');$q->execute([$_SESSION['admin_id']]);if($x=$q->fetch())out(['success'=>true,'logged_in'=>true,'role'=>'admin','admin'=>$x]);unset($_SESSION['admin_id']);}
 if(!empty($_SESSION['doctor_id'])){$q=$pdo->prepare('SELECT id,username,name,specialty FROM doctors WHERE id=?');$q->execute([$_SESSION['doctor_id']]);if($x=$q->fetch())out(['success'=>true,'logged_in'=>true,'role'=>'doctor','doctor'=>$x]);unset($_SESSION['doctor_id']);}
 if(!empty($_SESSION['patient_id'])){$q=$pdo->prepare('SELECT id,name,phone,age,gender,address FROM patients WHERE id=?');$q->execute([$_SESSION['patient_id']]);if($x=$q->fetch())out(['success'=>true,'logged_in'=>true,'role'=>'patient','patient'=>$x]);unset($_SESSION['patient_id']);}out(['success'=>true,'logged_in'=>false]);
case 'register':
 $name=trim($in['name']??'');$phone=trim($in['phone']??'');$pw=(string)($in['password']??'');$age=(int)($in['age']??0);$gender=trim($in['gender']??'');$address=trim($in['address']??'');if(!$name||!$phone||strlen($pw)<6||$age<1||!$gender||!$address)out(['success'=>false,'message'=>'Complete all fields; password must be at least 6 characters.'],400);
 $q=$pdo->prepare('INSERT INTO patients(name,phone,password_hash,age,gender,address) VALUES(?,?,?,?,?,?)');try{$q->execute([$name,$phone,password_hash($pw,PASSWORD_DEFAULT),$age,$gender,$address]);}catch(PDOException $e){if($e->errorInfo[1]==1062)out(['success'=>false,'message'=>'This phone number is already registered.'],409);throw $e;}session_regenerate_id(true);unset($_SESSION['admin_id'],$_SESSION['doctor_id']);$_SESSION['patient_id']=(int)$pdo->lastInsertId();out(['success'=>true,'patient'=>['id'=>$_SESSION['patient_id'],'name'=>$name,'phone'=>$phone,'age'=>$age,'gender'=>$gender,'address'=>$address]]);
case 'login':$q=$pdo->prepare('SELECT id,name,phone,password_hash,age,gender,address FROM patients WHERE phone=?');$q->execute([trim($in['phone']??'')]);$x=$q->fetch();if(!$x||!password_verify((string)($in['password']??''),$x['password_hash']))out(['success'=>false,'message'=>'Invalid phone number or password.'],401);unset($x['password_hash']);session_regenerate_id(true);session_unset();$_SESSION['patient_id']=(int)$x['id'];out(['success'=>true,'patient'=>$x]);
case 'admin_login':$q=$pdo->prepare('SELECT id,username,name,password_hash FROM admins WHERE username=?');$q->execute([trim($in['username']??'')]);$x=$q->fetch();if(!$x||!password_verify((string)($in['password']??''),$x['password_hash']))out(['success'=>false,'message'=>'Invalid admin username or password.'],401);unset($x['password_hash']);session_regenerate_id(true);session_unset();$_SESSION['admin_id']=(int)$x['id'];out(['success'=>true,'admin'=>$x]);
case 'doctor_login':$q=$pdo->prepare('SELECT id,username,name,specialty,password_hash FROM doctors WHERE username=? AND is_active=1');$q->execute([trim($in['username']??'')]);$x=$q->fetch();if(!$x||!password_verify((string)($in['password']??''),$x['password_hash']))out(['success'=>false,'message'=>'Invalid doctor username or password.'],401);unset($x['password_hash']);session_regenerate_id(true);session_unset();$_SESSION['doctor_id']=(int)$x['id'];out(['success'=>true,'doctor'=>$x]);
case 'logout':$_SESSION=[];if(ini_get('session.use_cookies')){$c=session_get_cookie_params();setcookie(session_name(),'',(int)(time()-42000),$c['path'],$c['domain'],$c['secure'],$c['httponly']);}session_destroy();out(['success'=>true]);
case 'doctors':$q=$pdo->query('SELECT id,name,specialty FROM doctors WHERE is_active=1 ORDER BY name');out(['success'=>true,'doctors'=>$q->fetchAll()]);
case 'slots':patient();$did=(int)($in['doctor_id']??0);$date=$in['date']??'';if(!$did||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))out(['success'=>false,'message'=>'Choose a doctor and valid date.'],400);$q=$pdo->prepare('SELECT id,slot_time FROM doctor_slots WHERE doctor_id=? AND slot_date=? AND is_available=1 ORDER BY slot_time');$q->execute([$did,$date]);out(['success'=>true,'slots'=>$q->fetchAll()]);
case 'book':$pid=patient();$sid=(int)($in['slot_id']??0);$did=(int)($in['doctor_id']??0);$date=$in['date']??'';$problem=trim($in['problem_description']??'');if(!$sid||!$did||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))out(['success'=>false,'message'=>'Choose a doctor, date and time.'],400);if(mb_strlen($problem)>2000)out(['success'=>false,'message'=>'Problem description is too long.'],400);$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM doctor_slots WHERE id=? FOR UPDATE');$q->execute([$sid]);$slot=$q->fetch();if(!$slot||(int)$slot['doctor_id']!==$did||$slot['slot_date']!==$date||(int)$slot['is_available']!==1){$pdo->rollBack();out(['success'=>false,'message'=>'That time is no longer available. Please choose another.'],409);} $q=$pdo->prepare('INSERT INTO appointments(patient_id,doctor_id,slot_id,appointment_date,appointment_time,problem_description,status) VALUES(?,?,?,?,?,?,\'PENDING\')');$q->execute([$pid,$did,$sid,$date,$slot['slot_time'],$problem]);$q=$pdo->prepare('UPDATE doctor_slots SET is_available=0 WHERE id=?');$q->execute([$sid]);$pdo->commit();out(['success'=>true,'message'=>'Appointment booked and sent to admin for confirmation.']);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
case 'patient_appointments':$pid=patient();$q=$pdo->prepare('SELECT a.id,a.appointment_date,a.appointment_time,a.status,a.problem_description,d.name doctor_name,d.specialty FROM appointments a JOIN doctors d ON d.id=a.doctor_id WHERE a.patient_id=? ORDER BY a.appointment_date DESC,a.appointment_time DESC');$q->execute([$pid]);out(['success'=>true,'appointments'=>$q->fetchAll()]);
case 'admin_appointments':admin();$q=$pdo->query('SELECT a.id,a.appointment_date,a.appointment_time,a.status,a.problem_description,p.name patient_name,p.phone patient_phone,d.name doctor_name,d.specialty FROM appointments a JOIN patients p ON p.id=a.patient_id JOIN doctors d ON d.id=a.doctor_id ORDER BY a.appointment_date DESC,a.appointment_time');out(['success'=>true,'appointments'=>$q->fetchAll()]);
case 'doctor_appointments':$did=doctor();$q=$pdo->prepare('SELECT a.id,a.appointment_date,a.appointment_time,a.status,a.problem_description,p.name patient_name,p.phone patient_phone FROM appointments a JOIN patients p ON p.id=a.patient_id WHERE a.doctor_id=? AND a.appointment_date=CURDATE() AND a.status<>\'CANCELLED\' ORDER BY a.appointment_time');$q->execute([$did]);out(['success'=>true,'appointments'=>$q->fetchAll()]);
case 'admin_confirm':admin();$aid=(int)($in['appointment_id']??0);$q=$pdo->prepare("UPDATE appointments SET status='CONFIRMED' WHERE id=? AND status='PENDING'");$q->execute([$aid]);out(['success'=>$q->rowCount()===1,'message'=>$q->rowCount()?'Appointment confirmed.':'Appointment not found or no longer pending.']);
case 'admin_cancel':admin();$aid=(int)($in['appointment_id']??0);$pdo->beginTransaction();$q=$pdo->prepare("SELECT slot_id,status FROM appointments WHERE id=? FOR UPDATE");$q->execute([$aid]);$a=$q->fetch();if(!$a||$a['status']==='CANCELLED'){$pdo->rollBack();out(['success'=>false,'message'=>'Appointment not found or already cancelled.'],404);}$q=$pdo->prepare("UPDATE appointments SET status='CANCELLED' WHERE id=?");$q->execute([$aid]);$q=$pdo->prepare('UPDATE doctor_slots SET is_available=1 WHERE id=?');$q->execute([$a['slot_id']]);$pdo->commit();out(['success'=>true,'message'=>'Appointment cancelled; time slot released.']);
case 'doctor_cancel':$did=doctor();$aid=(int)($in['appointment_id']??0);$pdo->beginTransaction();$q=$pdo->prepare("SELECT slot_id,status FROM appointments WHERE id=? AND doctor_id=? AND appointment_date=CURDATE() FOR UPDATE");$q->execute([$aid,$did]);$a=$q->fetch();if(!$a||$a['status']==='CANCELLED'){$pdo->rollBack();out(['success'=>false,'message'=>'Today\'s appointment not found or already cancelled.'],404);}$q=$pdo->prepare("UPDATE appointments SET status='CANCELLED' WHERE id=?");$q->execute([$aid]);$q=$pdo->prepare('UPDATE doctor_slots SET is_available=1 WHERE id=?');$q->execute([$a['slot_id']]);$pdo->commit();out(['success'=>true,'message'=>'Appointment cancelled.']);
default:out(['success'=>false,'message'=>'Unknown API action.'],400);
}}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log($e);out(['success'=>false,'message'=>'Server error. Check the PHP error log and database schema.'],500);}
